#!/usr/bin/python3
"""Tests for honey-review-desk-install (generated by agents-bots-honey.org). Everything runs against a staging directory
(HONEY_REVIEW_DESK_INITD_DIR); nothing here can write to the real /etc/init.d, and the one test that runs the installer WITHOUT a staging directory
is skipped when the caller is root. HONEY_REVIEW_DESK_INSTALL=/path overrides the installer under test (the mutation proof uses it)."""
import os, re, shutil, stat, subprocess, tempfile, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
CAND = [os.environ.get('HONEY_REVIEW_DESK_INSTALL', ''), os.path.join(HERE, '..', 'openrc', 'honey-review-desk-install'), os.path.join(HERE, 'honey-review-desk-install')]
INSTALL = next(os.path.abspath(c) for c in CAND if c and os.path.isfile(c))


def rd(p):
    with open(p) as fh:
        return fh.read()


def wr(p, t):
    with open(p, 'w') as fh:
        fh.write(t)


class Lane(unittest.TestCase):
    """A copy of the installer in a scratch lane (lane/bin/ + lane/openrc/honey-review-desk) and a staging init.d."""
    UNIT = '#!/sbin/openrc-run\nname="honey-review-desk"\ncommand="/usr/bin/python3"\nstop() {\n    return 0\n}\n'

    def setUp(self):
        self.d = tempfile.mkdtemp(prefix='hrdi-'); self.addCleanup(shutil.rmtree, self.d, True)
        self.lane = os.path.join(self.d, 'lane'); os.makedirs(os.path.join(self.lane, 'openrc')); os.makedirs(os.path.join(self.lane, 'bin'))
        self.script = os.path.join(self.lane, 'bin', 'honey-review-desk-install'); shutil.copy(INSTALL, self.script); os.chmod(self.script, 0o755)
        self.src = os.path.join(self.lane, 'openrc', 'honey-review-desk'); wr(self.src, self.UNIT)
        self.initd = os.path.join(self.d, 'init.d'); os.makedirs(self.initd)
        self.dst = os.path.join(self.initd, 'honey-review-desk')

    def run_(self, *args, staging=True, env=None):
        e = dict(os.environ, **(env or {}))
        e.pop('HONEY_REVIEW_DESK_INITD_DIR', None)
        if staging: e['HONEY_REVIEW_DESK_INITD_DIR'] = self.initd
        return subprocess.run([self.script, *args], capture_output=True, text=True, env=e, timeout=60)


class Check(Lane):
    def test_missing(self):
        p = self.run_('check'); self.assertEqual(p.returncode, 1); self.assertTrue(p.stdout.startswith('missing '))

    def test_unchanged(self):
        wr(self.dst, self.UNIT); p = self.run_('check'); self.assertEqual(p.returncode, 0); self.assertTrue(p.stdout.startswith('unchanged '))

    def test_drift_shows_the_diff_and_exits_1(self):
        wr(self.dst, self.UNIT.replace('return 0', 'return 1')); p = self.run_('check')
        self.assertEqual(p.returncode, 1); self.assertTrue(p.stdout.startswith('drift ')); self.assertIn('-    return 1', p.stdout); self.assertIn('+    return 0', p.stdout)

    def test_check_is_the_default_and_changes_nothing(self):
        before = rd(self.src); p = self.run_(); self.assertEqual(p.returncode, 1)
        self.assertEqual(os.listdir(self.initd), []); self.assertEqual(rd(self.src), before)

    def test_a_long_diff_is_cut_at_forty_lines(self):
        wr(self.src, self.UNIT + ''.join('# line %d\n' % i for i in range(200))); wr(self.dst, self.UNIT)
        self.assertLessEqual(len(self.run_('check').stdout.splitlines()), 42)


class Install(Lane):
    def test_install_places_exactly_one_file_with_mode_755(self):
        p = self.run_('install'); self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(os.listdir(self.initd), ['honey-review-desk']); self.assertEqual(rd(self.dst), self.UNIT)
        self.assertEqual(stat.S_IMODE(os.stat(self.dst).st_mode), 0o755)

    def test_install_backs_up_a_different_file_first(self):
        wr(self.dst, 'old\n'); self.run_('install')
        baks = [n for n in os.listdir(self.initd) if n.startswith('honey-review-desk.bak-')]
        self.assertEqual(len(baks), 1); self.assertEqual(rd(os.path.join(self.initd, baks[0])), 'old\n'); self.assertEqual(rd(self.dst), self.UNIT)

    def test_install_twice_is_a_no_op_and_makes_no_second_backup(self):
        self.run_('install'); p = self.run_('install')
        self.assertIn('unchanged', p.stdout); self.assertEqual(sorted(os.listdir(self.initd)), ['honey-review-desk'])

    def test_dry_run_changes_nothing_and_says_what_it_would_do(self):
        wr(self.dst, 'old\n'); p = self.run_('--dry-run', 'install')
        self.assertIn('would: backup and install', p.stdout); self.assertEqual(rd(self.dst), 'old\n'); self.assertEqual(os.listdir(self.initd), ['honey-review-desk'])

    def test_a_source_that_does_not_parse_is_refused(self):
        wr(self.src, '#!/sbin/openrc-run\nstop() {\n'); p = self.run_('install')
        self.assertEqual(p.returncode, 1); self.assertIn('does not parse', p.stderr); self.assertEqual(os.listdir(self.initd), [])

    def test_a_missing_source_is_refused(self):
        os.remove(self.src)
        for verb in ('install', 'check'):
            p = self.run_(verb); self.assertEqual(p.returncode, 1); self.assertIn('missing %s' % self.src, p.stderr); self.assertEqual(os.listdir(self.initd), [])

    @unittest.skipIf(os.geteuid() == 0, 'SKIPPED: this test runs the installer without a staging directory, which as root would touch the real /etc/init.d')
    def test_without_a_staging_directory_it_requires_root_and_writes_nothing(self):
        p = self.run_('install', staging=False)
        self.assertEqual(p.returncode, 1); self.assertIn('requires root', p.stderr)

    def test_unknown_argument_is_exit_2(self):
        self.assertEqual(self.run_('--bogus').returncode, 2)


class Scope(unittest.TestCase):
    def test_it_never_starts_stops_or_enables_anything_and_never_touches_the_app(self):
        code = '\n'.join(l for l in rd(INSTALL).splitlines() if not l.strip().startswith('#'))
        code = re.sub(r"echo 'No service was started, restarted, or enabled.'", '', code)
        for needle in ('rc-service', 'rc-update', 'service ', 'start-stop-daemon', 'kill', 'systemctl', 'honey-centre', '/etc/rc', 'ln -s', 'curl', 'ssh'):
            self.assertNotIn(needle, code, needle)

    def test_it_places_one_named_file_only(self):
        text = rd(INSTALL)
        self.assertEqual(text.count('install -D -m 0755'), 2)  # the root and the staging variant of the same single install; both name $SRC and $DST
        self.assertEqual(re.findall(r'DST="\$INITD/([a-z-]+)"', text), ['honey-review-desk'])
        self.assertEqual(len(re.findall(r'-- "\$SRC" "\$DST"', text)), 2)


if __name__ == '__main__':
    unittest.main(verbosity=2)
